# Code generated by Claude
"""Bench stance selection by an inverse-reach region (David 2026-10-23, step 3 part C, decisions-log M170 to M172; replaces the measured bench rectangle).

    maps = load_maps("data/reach_map")                                        # {(side, bin): ReachMap}, with the files' stamps
    reg = get_region(maps, robot, cams, depth, z_points, cfg=BENCH_STANCE_CFG)  # one object's region (cached)
    res = overlay(objects, maps, robot, cams, bench, extra_blocked=None, cfg=BENCH_STANCE_CFG)    # the best (x, y, pedestal) for a list of objects

The robot faces the bench: its heading is fixed, perpendicular to the bench edge, so the base frame has x towards the bench and y along it (to the left). Everything below is in that frame or in the
"bench frame" (n = the direction the robot faces, t = n turned 90 degrees to the left).

Region (C2b). For one arm, an object's depth from the bench edge and the heights of its grasp-band points, the region is a stack (one array per pedestal command) over the floor spots (1 cm) of the base
origin, written as (b, o): b = how far ahead of the base the object is, o = how far to the left. A cell holds the number of bench-approach bins (BENCH_STANCE_CFG["approach_bins"]) in which at least one
grasp-band height is reachable at that spot (the reach map of that arm and bin, looked up in the shoulder frame at the pedestal height), when the eagle camera sees the target with the framing margin
(STANCE_REQUIREMENTS["view_min_margin"], the grasp-band's lowest and highest point both), else 0. It depends only on the object relative to the base, so sliding the object along the bench slides the
region; it is cached by (arm, depth, heights, bench_open, the maps' stamps, the robot and camera numbers). Array lookups only: no IK, no simulation.
Two of the three geometry filters of the spec are NOT in the cached region (they depend on where along the bench the spot is): the base footprint against the bench legs, walls and other furniture and the
zombie pose's 40 mm clearance to the bench are applied in the overlay by `extra_blocked` (the stance finder's FurnitureMap.blocked and HomeClearanceMap.clear_mask, built by the pipeline); the result
for a cell is the same (M172).

Obstacle filter (C2c, plan time, not cached): other objects are vertical cylinders (position, radius, z range) grown by a margin. For a cell, a pedestal height and a bin, the arm's swept volume is the chain
shoulder -> pre-grasp point -> grasp point thickened by the arm's radius; a bin whose chain meets any cylinder is removed from that cell (the count only goes down).

Overlay and scoring (C2d): the objects' filtered regions are placed at the objects' positions on one floor grid; each (cell, pedestal) is scored by (1) the number of objects reachable (count > 0), (2) the
smallest count over the reachable ones, (3) the distance from the cell to the edge of the region where that many objects are reachable, (4) the distance to the nearest obstacle cylinder; compared in that order,
the distance (3) rounded to 1 cm.

Contents:
    BenchStanceError, load_maps, maps_stamp, bench_frame, camera_poses, pedestal_commands, build_region, get_region, counts, filter_obstacles, count_at, make_extra_blocked, robot_silhouettes, gripper_view_ok, hidden_fraction, spec_in_base_frame, box_surface_samples, cylinder_surface_samples, widest_run, overlay.
"""

import hashlib
import json
import math
import time
from pathlib import Path

import numpy as np
from scipy import ndimage

from src.reach_map import load_map
from src.task_config import BENCH_STANCE_CFG, PICK_PLACE_CFG, STANCE_CFG, STANCE_REQUIREMENTS

PROJECT_ROOT = Path(__file__).resolve().parents[1]


class BenchStanceError(RuntimeError):
    """No stance covers the objects; the message names the blockers."""


def load_maps(path, sides=("left", "right")):
    """The finished reach maps of a folder: {(side, bin): ReachMap}, one per file, not merged; `maps_stamp(maps, arm)` of the result tells which build they are.

    Args:
        path (str or Path): The folder.
        sides (tuple of str): Which arms to load. Defaults to both.
    """
    maps = {}
    for f in sorted(p for s in sides for p in Path(path).glob(f"{s}_bin*.npz")):
        rm = load_map(f)
        rm.stamp = str(np.load(f)["stamp"])
        maps[(rm.side, rm.bin)] = rm
    return maps


def maps_stamp(maps, arm):
    """A short hash of the stamps of one arm's maps (part of the cache key)."""
    return hashlib.sha256(json.dumps(sorted((k[1], getattr(m, "stamp", "")) for k, m in maps.items() if k[0] == arm)).encode()).hexdigest()[:16]


def bench_frame(yaw):
    """The bench frame for a robot heading that faces the bench: (n, t): n the heading's unit vector, t it turned 90 degrees to the left (world xy)."""
    return np.array([math.cos(yaw), math.sin(yaw)]), np.array([-math.sin(yaw), math.cos(yaw)])


def camera_poses(model, qs, camera="eagle_cam", chk=None, ref_stance=None, cache_dir=None):
    """The eagle camera's pose in the base frame for each pedestal command (the camera is fixed to the torso, so only the pedestal moves it).

    Args:
        model (mujoco.MjModel): The compiled model.
        qs (iterable of float): The pedestal commands.
        camera (str): The camera name. Defaults to "eagle_cam".
        chk (src.stance_checks.StanceChecks or None): With it (and ref_stance), the robot's silhouettes ("sil", see robot_silhouettes) and the grippers-in-view flags ("grip", gripper_view_ok) are added.
        ref_stance (tuple or None): (x, y, yaw) where the silhouettes are rendered. Defaults to None.
        cache_dir (str or Path or None): Where the silhouettes are kept.

    Returns:
        dict: {"qs", "pos" (nq, 3), "R" (nq, 3, 3) (camera axes in the base frame), "W", "H" (pixels), "fovy" (degrees)}, plus "sil" (bool (nq, H, W)) and "grip" (bool (nq,)) when chk is given.
    """
    import mujoco
    from src import robot_specs
    d = mujoco.MjData(model)
    root, c = model.body("base_link").id, model.camera(camera).id
    pos, R = [], []
    for q in qs:
        for jn in robot_specs.PEDESTAL_SPECS["joints"]:
            d.qpos[model.joint(jn).qposadr[0]] = float(q)
        mujoco.mj_kinematics(model, d)
        mujoco.mj_camlight(model, d)
        Rb, pb = d.xmat[root].reshape(3, 3), d.xpos[root]
        pos.append(Rb.T @ (d.cam_xpos[c] - pb))
        R.append(Rb.T @ d.cam_xmat[c].reshape(3, 3))
    W, H = [float(v) for v in model.cam_resolution[c]]
    out = {"qs": [float(q) for q in qs], "pos": np.array(pos), "R": np.array(R), "W": W, "H": H, "fovy": float(model.cam_fovy[c])}
    if chk is not None:
        out["sil"] = robot_silhouettes(model, chk, qs, ref_stance, camera, cache_dir)
        out["grip"] = gripper_view_ok(chk, qs, ref_stance)
        out["arm_pts"] = arm_points(model, chk)
    return out


def pedestal_commands(cfg=BENCH_STANCE_CFG):
    """The pedestal commands searched, metres (BENCH_STANCE_CFG["pedestal_range"] every "pedestal_step")."""
    lo, hi = cfg["pedestal_range"]
    return [round(float(v), 6) for v in np.arange(lo, hi + 1e-9, cfg["pedestal_step"])]


def _axes(cfg):
    res = cfg["grid_m"]
    b = np.arange(cfg["forward_range"][0], cfg["forward_range"][1] + 1e-9, res)
    o = np.arange(cfg["lateral_range"][0], cfg["lateral_range"][1] + 1e-9, res)
    return b, o


def _view_ok(cams, qi, bb, oo, pts, margin):
    """Whether the points (dx, dy, z) around the object at (b, o) (z above the base origin) are all inside the camera's image with the margin: bool like bb."""
    th = math.tan(math.radians(cams["fovy"]) / 2)
    W, H = cams["W"], cams["H"]
    ok = np.ones(bb.shape, bool)
    for dx, dy, z in pts:
        P = np.stack([bb + dx, oo + dy, np.full(bb.shape, z)], axis=-1)
        pc = (P - cams["pos"][qi]) @ cams["R"][qi]
        depth = -pc[..., 2]
        safe = np.maximum(depth, 1e-6)
        u, v = pc[..., 0] / safe / (th * W / H), pc[..., 1] / safe / th
        m = np.where(depth < 0.05, -1.0, np.minimum((1 - np.abs(u)) / 2, (1 - np.abs(v)) / 2))
        ok &= m >= margin - 1e-9
    return ok


def spec_in_base_frame(obj, yaw, base_z):
    """An object's inputs to the region, in the base frame (x towards the bench, y to the left; z above the base origin): the world offsets of its corners and surface samples turned by the heading.

    Args:
        obj (dict): "xy", "z_points", "surface_z", "corners" ((8, 3) world points of its bounding box), "samples" ((K, 3) world points on its surface), "hidden_max" (largest hidden share), optionally "radius_shape" (a cylinder's radius; with "z0", "z1") when the object is a cylinder rather than a box.
        yaw (float): The heading that faces the bench.
        base_z (float): The base origin's height above the floor.

    Returns:
        dict: "z_points" (above the base origin), "surface_z", "corners" (8, 3), "samples" (K, 3), "hidden_max".
    """
    n, t = bench_frame(yaw)
    xy = np.asarray(obj["xy"], float)

    def conv(P):
        P = np.asarray(P, float)
        d = P[:, :2] - xy
        return np.stack([d @ n, d @ t, P[:, 2] - base_z], axis=-1)
    corners = conv(obj["corners"])
    shape = ("cyl", float(obj["radius_shape"]), float(obj["z0"]) - base_z, float(obj["z1"]) - base_z) if obj.get("radius_shape") else ("box", corners.min(axis=0), corners.max(axis=0))
    return {"z_points": [float(z) - base_z for z in obj["z_points"]], "surface_z": float(obj["surface_z"]) - base_z, "corners": corners, "samples": conv(obj["samples"]),
            "hidden_max": float(obj["hidden_max"]), "shape": shape}


def build_region(maps, robot, cams, arm, spec, cfg=BENCH_STANCE_CFG, margin=STANCE_REQUIREMENTS["view_min_margin"]):
    """Builds one object's region (see the module docstring).

    Args:
        maps (dict): {(side, bin): ReachMap}.
        robot (dict): From stance_finder.robot_geometry.
        cams (dict): From camera_poses with chk (so with "sil" and "grip"), for the pedestal commands of `cfg`.
        arm (str): "left" or "right".
        spec (dict): From spec_in_base_frame.
        cfg (dict): BENCH_STANCE_CFG.
        margin (float): The framing margin, fraction of the image.

    Returns:
        dict: "bins", "qs", "b", "o" (the axes), "reach" (bool (nq, nbins, nb, no): every path point of the bin is reachable: the band heights, the standoff, over and lift points of src/task_points),
        "view" (bool (nq, nb, no): the bounding box's corners inside the view, both grippers at home inside the view, the object not hidden by more than the limit).
    """
    from src.task_points import path_offsets
    qs = cams["qs"]
    b, o = _axes(cfg)
    bb, oo = np.meshgrid(b, o, indexing="ij")
    sx, sy, sz = robot["shoulder"][arm]
    bins = list(cfg["approach_bins"])
    reach = np.zeros((len(qs), len(bins), len(b), len(o)), bool)
    view = np.zeros((len(qs), len(b), len(o)), bool)
    zs = [z + robot["base_z"] for z in spec["z_points"]]                    # world heights (the maps are looked up in the shoulder frame from the world height)
    surf = spec["surface_z"] + robot["base_z"]
    for qi, q in enumerate(qs):
        zt = robot["base_z"] + robot["torso_z0"] + robot["lift_factor"] * q + sz
        ok_view = _view_ok(cams, qi, bb, oo, spec["corners"], margin) if cams["grip"][qi] else np.zeros(bb.shape, bool)
        hid = np.zeros(bb.shape)
        if ok_view.any():
            hid = hidden_fraction(cams, cams["sil"], qi, bb, oo, spec["samples"])
        view[qi] = ok_view & (hid <= spec["hidden_max"] + cfg["hidden_tolerance"] * (spec["hidden_max"] == 0))
        if ok_view.any() and view[qi].any():                                # the arms at home keep the home clearance from this object (the finder's requirement; the furniture is the overlay's)
            ap = cams["arm_pts"].copy()
            ap[:, 2] += robot["lift_factor"] * q - robot["base_z"]
            idx = np.argwhere(view[qi])
            C = np.stack([b[idx[:, 0]], o[idx[:, 1]], np.zeros(len(idx))], axis=-1)
            keep = np.ones(len(idx), bool)
            for a0 in range(0, len(idx), 2000):
                sl = slice(a0, a0 + 2000)
                dm = (box_distance(ap, C[sl], spec["shape"][1], spec["shape"][2]) if spec["shape"][0] == "box" else cylinder_distance(ap, C[sl], *spec["shape"][1:])).min(axis=-1)
                keep[sl] = dm - 0.003 >= cfg["home_clearance_m"]
            view[qi][idx[~keep, 0], idx[~keep, 1]] = False
        for bi, k in enumerate(bins):
            rm = maps.get((arm, k))
            if rm is None:
                continue
            pts = [(0.0, 0.0, z) for z in zs] + [(dx, dy, z) for _, dx, dy, z in path_offsets(k, zs, surf)]
            ok = np.ones(bb.shape, bool)
            for dx, dy, z in pts:
                ix = np.floor((bb + dx - sx - rm.origin[0]) / rm.cube).astype(int)
                iy = np.floor((oo + dy - sy - rm.origin[1]) / rm.cube).astype(int)
                iz = int(np.floor((z - zt - rm.origin[2]) / rm.cube))
                if not 0 <= iz < rm.cubes.shape[2]:
                    ok[:] = False
                    break
                inb = (ix >= 0) & (ix < rm.cubes.shape[0]) & (iy >= 0) & (iy < rm.cubes.shape[1])
                hit = np.zeros(bb.shape, bool)
                hit[inb] = rm.cubes[ix[inb], iy[inb], iz]
                ok &= hit
            reach[qi, bi] = ok
    return {"bins": bins, "qs": list(qs), "b": b, "o": o, "reach": reach, "view": view}


def _key(maps, robot, cams, arm, depth, spec, bench_open, cfg):
    blob = json.dumps({"arm": arm, "depth": round(float(depth), 4), "z": [round(float(z), 4) for z in spec["z_points"]], "surface": round(spec["surface_z"], 4), "bench_open": bool(bench_open),
                       "corners": np.round(spec["corners"], 4).tolist(), "samples": hashlib.sha256(np.round(spec["samples"], 4).tobytes()).hexdigest()[:12], "hidden": [spec["hidden_max"], cfg["hidden_tolerance"]],
                       "stamp": maps_stamp(maps, arm), "bins": list(cfg["approach_bins"]), "grid": cfg["grid_m"], "fwd": cfg["forward_range"], "lat": cfg["lateral_range"],
                       "qs": [round(q, 5) for q in cams["qs"]], "cam": np.round(np.concatenate([cams["pos"].ravel(), cams["R"].ravel()]), 4).tolist(), "fov": cams["fovy"],
                       "sil": hashlib.sha256(np.packbits(cams["sil"]).tobytes()).hexdigest()[:12], "grip": cams["grip"].tolist(),
                       "robot": [round(float(robot["base_z"]), 4), round(float(robot["torso_z0"]), 4), round(float(robot["lift_factor"]), 4), np.round(robot["shoulder"][arm], 4).tolist()],
                       "margin": STANCE_REQUIREMENTS["view_min_margin"], "pick_place": [PICK_PLACE_CFG["standoff_m"], PICK_PLACE_CFG["clearance_m"]], "home": [cfg["home_clearance_m"], hashlib.sha256(np.round(cams["arm_pts"], 3).tobytes()).hexdigest()[:12], spec["shape"][0]], "version": 3}, sort_keys=True)
    return hashlib.sha256(blob.encode()).hexdigest()[:24]


def get_region(maps, robot, cams, depth, spec, arm=None, bench_open=True, cfg=BENCH_STANCE_CFG, use_cache=True, say=print):
    """The cached region (builds and caches it when absent).

    Args:
        maps (dict): {(side, bin): ReachMap} from load_maps.
        robot (dict): From stance_finder.robot_geometry.
        cams (dict): From camera_poses (with the silhouettes).
        depth (float): The object's distance from the bench edge to its centre, metres (in the key).
        spec (dict): From spec_in_base_frame.
        arm (str or None): Defaults to cfg["arm"].
        bench_open (bool): TASK_CFG["bench_open"] (in the key).
        cfg (dict): BENCH_STANCE_CFG.
        use_cache (bool): Read and write the cache. Defaults to True.
        say (callable): Progress lines.

    Returns:
        dict: As build_region, plus "seconds" (build time, 0 when read from the cache) and "cached" (bool).
    """
    arm = arm or cfg["arm"]
    key = _key(maps, robot, cams, arm, depth, spec, bench_open, cfg)
    path = Path(PROJECT_ROOT) / cfg["cache_dir"] / f"{arm}_{key}.npz"
    if use_cache and path.exists():
        try:
            z = np.load(path)
            return {"bins": [int(v) for v in z["bins"]], "qs": [float(v) for v in z["qs"]], "b": z["b"], "o": z["o"], "reach": np.unpackbits(z["reach"])[:int(np.prod(z["rshape"]))].reshape(z["rshape"]).astype(bool),
                    "view": z["view"], "seconds": 0.0, "cached": True}
        except Exception as e:                                         # a half-written or damaged file: rebuild
            say(f"[bench_stance] cache file {path.name} unreadable ({e}); rebuilding")
    t0 = time.time()
    reg = build_region(maps, robot, cams, arm, spec, cfg)
    reg["seconds"], reg["cached"] = time.time() - t0, False
    if use_cache:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp.npz")
        np.savez_compressed(tmp, bins=np.array(reg["bins"]), qs=np.array(reg["qs"]), b=reg["b"], o=reg["o"], reach=np.packbits(reg["reach"]), rshape=np.array(reg["reach"].shape), view=reg["view"])
        tmp.replace(path)
    return reg


def counts(reg, bins=None, ok=None):
    """The count array (nq, nb, no): bins reachable, zero where the camera does not see the target. `bins`: bool (nq, nbins, nb, no) overrides the reach (the filtered one); `ok`: bool (nq, nb, no),
    False where a plan-time filter (the support objects, H) zeroes the count."""
    r = reg["reach"] if bins is None else bins
    c = r.sum(axis=1) * reg["view"]
    if ok is not None:
        c = c * ok
    return c.astype(np.int16)


def support_ok(reg, robot, cams, supports, yaw, cfg=BENCH_STANCE_CFG):
    """H: False where, at a pedestal height and floor spot, the zombie pose's arms come within the home clearance (40 mm, STANCE_REQUIREMENTS) of a support object under the target.

    Args:
        reg (dict): The target's region.
        robot (dict): From robot_geometry.
        cams (dict): From camera_poses (with "arm_pts").
        supports (list of dict): Each {"kind": "box" with "xy" (world centre), "half" (hx, hy, world axes), "z0", "z1"} or {"kind": "cylinder", "xy", "radius", "z0", "z1"}; "target_xy" is the target's world xy.
        yaw (float): The heading that faces the bench.
        cfg (dict): BENCH_STANCE_CFG.

    Returns:
        numpy.ndarray: Bool (nq, nb, no), True where the arms keep the clearance from every support (all True with no supports). Geometry on known shapes, no IK; only the spots that already have a count are tested.
    """
    ok = np.ones(reg["view"].shape, bool)
    if not supports:
        return ok
    n, t = bench_frame(yaw)
    b, o = reg["b"], reg["o"]
    base_z = robot["base_z"]
    pts0 = cams["arm_pts"]
    live = (reg["reach"].any(axis=1) & reg["view"])                          # (nq, nb, no): the cells that have a count
    lim = cfg["home_clearance_m"] + 0.003
    for qi, q in enumerate(reg["qs"]):
        idx = np.argwhere(live[qi])
        if not len(idx):
            continue
        ap = pts0.copy()
        ap[:, 2] += robot["lift_factor"] * q - base_z
        C = np.stack([b[idx[:, 0]], o[idx[:, 1]], np.zeros(len(idx))], axis=-1)       # the target's base-frame position per spot (b ahead, o left)
        bad = np.zeros(len(idx), bool)
        for sp in supports:
            d_xy = np.asarray(sp["xy"], float) - np.asarray(sp["target_xy"], float)
            rel = np.array([d_xy @ n, d_xy @ t])
            cen = C.copy()
            cen[:, 0] += rel[0]
            cen[:, 1] += rel[1]
            z0, z1 = sp["z0"] - base_z, sp["z1"] - base_z
            if sp["kind"] == "cylinder":
                dm = cylinder_distance(ap, cen, sp["radius"], z0, z1).min(axis=-1)
            else:
                hx, hy = sp["half"]
                ex, ey = abs(n[0]) * hx + abs(n[1]) * hy, abs(t[0]) * hx + abs(t[1]) * hy        # the world box's half sizes along the bench frame (exact for a heading that is a multiple of 90 degrees)
                dm = box_distance(ap, cen, np.array([-ex, -ey, z0]), np.array([ex, ey, z1])).min(axis=-1)
            bad |= dm < lim
        ok[qi][idx[bad, 0], idx[bad, 1]] = False
    return ok


def filter_obstacles(reg, robot, arm, z_grasp, obstacles, cfg=BENCH_STANCE_CFG):
    """Removes the bins whose arm chain meets an obstacle cylinder (C2c; see the module docstring).

    Args:
        reg (dict): The object's region.
        robot (dict): From robot_geometry.
        arm (str): The arm.
        z_grasp (float): World height of the grasp point (the middle of the band), metres.
        obstacles (list of dict): Each {"rel": (db, do): the cylinder's centre relative to the target in the bench frame (along n, along t), "radius", "z0", "z1" (world heights)}.
        cfg (dict): BENCH_STANCE_CFG.

    Returns:
        numpy.ndarray: Bool (nq, nbins, nb, no): the region's reach with the blocked bins cleared.
    """
    reach = reg["reach"].copy()
    if not obstacles:
        return reach
    b, o = reg["b"], reg["o"]
    bb, oo = np.meshgrid(b, o, indexing="ij")
    sx, sy, sz = robot["shoulder"][arm]
    n = int(cfg["chain_samples"])
    s = np.linspace(0.0, 1.0, n)[:, None]
    rr = cfg["obstacle_margin_m"] + cfg["arm_radius_m"]
    for qi, q in enumerate(reg["qs"]):
        zs = robot["base_z"] + robot["torso_z0"] + robot["lift_factor"] * q + sz
        for bi, k in enumerate(reg["bins"]):
            sel = reach[qi, bi]
            if not sel.any():
                continue
            ang = math.radians(30.0 * k)
            gx, gy = bb[sel], oo[sel]                                                              # the grasp points (base frame xy), only where the bin is reachable
            px, py = gx - cfg["hand_standoff_m"] * math.cos(ang), gy - cfg["hand_standoff_m"] * math.sin(ang)   # the pre-grasp points
            # the chain: shoulder -> pre-grasp point (the height going linearly from the shoulder's to the grasp height), then pre-grasp -> grasp point at the grasp height
            segs = ((sx + s * (px - sx), sy + s * (py - sy), zs + s * (z_grasp - zs), np.hypot(px - sx, py - sy) / (n - 1)),
                    (px + s * (gx - px), py + s * (gy - py), np.full((n, 1), z_grasp), np.hypot(gx - px, gy - py) / (n - 1)))
            hit = np.zeros(gx.shape, bool)
            for ob in obstacles:
                cx, cy = gx + ob["rel"][0], gy + ob["rel"][1]                                       # the cylinder's axis in the base frame, per grasp point
                for xx, yy, zz, step in segs:
                    dz = np.maximum(np.maximum(ob["z0"] - zz, zz - ob["z1"]), 0.0)
                    d = np.hypot(np.maximum(np.hypot(xx - cx, yy - cy) - ob["radius"], 0.0), dz).min(axis=0)
                    hit |= d < rr + 0.5 * step                                                      # half the sample spacing: a conservative allowance for the points between samples
            keep = sel.copy()
            keep[sel] = ~hit
            reach[qi, bi] = keep
    return reach


def _shift(B, dy, dx):
    """B shifted so that out[iy, ix] = B[iy + dy, ix + dx] (False outside)."""
    out = np.zeros_like(B)
    ny, nx = B.shape
    ys, xs = slice(max(0, -dy), min(ny, ny - dy)), slice(max(0, -dx), min(nx, nx - dx))
    yd, xd = slice(max(0, dy), min(ny, ny + dy)), slice(max(0, dx), min(nx, nx + dx))
    out[ys, xs] = B[yd, xd]
    return out


def creep_blocked(furniture, footprint, yaw, back_m, margin_m=0.01, heading_err_deg=1.0):
    """H2: the base positions from which the creep-in path to the stance is not clear: the stance is where the path ends, the path is a straight line of length back_m from the approach spot behind it (the robot
    faces the bench along it); the base footprint, grown by the stopping error (margin_m, and the heading +- heading_err_deg), swept along it must stay clear of the furniture map's BASE layer (bench legs, walls).

    Args:
        furniture (src.furniture_map.FurnitureMap): The scene's furniture map.
        footprint (numpy.ndarray): The base footprint (K, 2), base frame.
        yaw (float): The heading (facing the bench).
        back_m (float): The creep-in distance, metres (TASK_CFG["staging_approach_back_m"]).
        margin_m, heading_err_deg (float): The stopping error the corridor is widened by.

    Returns:
        numpy.ndarray: Bool, the grid of the furniture map: True where the creep-in path ending at that cell clips something.
    """
    ring = margin_m * np.array([[math.cos(a), math.sin(a)] for a in np.linspace(0, 2 * math.pi, 8, endpoint=False)])
    pts = (np.asarray(footprint, float)[:, None, :] + ring[None]).reshape(-1, 2)
    from scipy.spatial import ConvexHull
    grown = pts[ConvexHull(pts).vertices]
    out = np.zeros(furniture.shape, bool)
    steps = int(math.ceil(back_m / furniture.res))
    for th in (yaw - math.radians(heading_err_deg), yaw, yaw + math.radians(heading_err_deg)):
        c, s = math.cos(th), math.sin(th)
        B = furniture._grow("base", grown @ np.array([[c, s], [-s, c]]))
        for k in range(steps + 1):
            d = min(k * furniture.res, back_m)
            # the footprint is at the cell minus d along the heading when the robot has crept d metres of the way
            dx, dy = int(round(-d * math.cos(yaw) / furniture.res)), int(round(-d * math.sin(yaw) / furniture.res))
            out |= _shift(B, dy, dx)
    return out


def make_extra_blocked(furniture, robot, yaw, home_clear=None, heading_robust_deg=STANCE_CFG["heading_robust_deg"], creep_back_m=None, creep_error=None):
    """The `extra_blocked` function of overlay for the real scene: the stance finder's furniture map (base layer grown by the footprint, arm layer by the torso-and-pedestal column; at the heading and
    +- the heading robustness) and, if given, the arms-at-home clearance (HomeClearanceMap.clear_mask).

    Args:
        furniture (src.furniture_map.FurnitureMap): The scene's furniture map.
        robot (dict): From robot_geometry.
        yaw (float): The heading, radians.
        home_clear (callable or None): robot["home_clear"] style f(heading, qs, X, Y) -> bool (nq, ny, nx), True where clear.
        heading_robust_deg (float): The heading error the stance must survive.
        creep_back_m (float or None): With it, a spot whose creep-in path (this long, straight, ending at the spot) clips the furniture's base layer is blocked at every height (H2, creep_blocked).
        creep_error (tuple or None): (position margin m, heading error deg) the creep corridor is widened by. Defaults to (0.01, 1.0).

    Returns:
        callable: f(X, Y, qs) -> bool (nq, ny, nx), True where the base origin may not be.
    """
    d = math.radians(heading_robust_deg)
    creep = None if creep_back_m is None else creep_blocked(furniture, robot["footprint"], yaw, creep_back_m, *(creep_error or (0.01, 1.0)))

    def f(X, Y, qs):
        ix = np.floor((X - furniture.origin[0]) / furniture.res).astype(int)
        iy = np.floor((Y - furniture.origin[1]) / furniture.res).astype(int)
        inb = (ix >= 0) & (ix < furniture.shape[1]) & (iy >= 0) & (iy < furniture.shape[0])
        out = np.ones((len(qs),) + X.shape, bool)
        for qi, q in enumerate(qs):
            col = robot.get("column")
            blocked = np.zeros(X.shape, bool)
            for th in ([yaw - d, yaw, yaw + d] if d else [yaw]):
                B = furniture.blocked(th, robot["footprint"], None if col is None else col(float(q)))
                blocked |= np.where(inb, B[np.clip(iy, 0, furniture.shape[0] - 1), np.clip(ix, 0, furniture.shape[1] - 1)], True)
            out[qi] = blocked
        if home_clear is not None:
            out |= ~np.asarray(home_clear(yaw, qs, X, Y), bool)
        if creep is not None:
            out |= np.where(inb, creep[np.clip(iy, 0, furniture.shape[0] - 1), np.clip(ix, 0, furniture.shape[1] - 1)], True)[None]
        return out
    return f


def robot_silhouettes(model, chk, qs, stance_xy_yaw, camera="eagle_cam", cache_dir=None, say=print):
    """The robot's silhouette in the eagle image at the zombie pose for each pedestal command (F3): bool (nq, H, W), True where a robot geom is the nearest surface.

    The camera is fixed to the torso, so for a given pedestal command the robot looks the same from the camera wherever the base stands (F0c, checked by experiments/f0_silhouette_check.py);
    the mask is the union of two renders at one stance: the robot alone (every geom that is not under base_link made fully transparent) and the robot in the scene (the picture the occlusion measure of src/stance_checks.py sees; the two differ by about 2.5 % of the arm pixels where the arm and the bench are nearly at the same depth, F0).

    Args:
        model (mujoco.MjModel): The compiled model (with the eagle camera).
        chk (src.stance_checks.StanceChecks): Places the robot at a stance with both arms at home.
        qs (iterable of float): The pedestal commands.
        stance_xy_yaw (tuple): (x, y, yaw) where the robot is placed for the renders (any stance gives the same silhouette).
        camera (str): The camera. Defaults to "eagle_cam".
        cache_dir (str or Path or None): A folder to keep the masks in (an npz named by a hash of the camera pose and the home pose); None: not cached.
        say (callable): Progress lines.

    Returns:
        numpy.ndarray: Bool (nq, H, W).
    """
    import copy
    import mujoco
    qs = [float(q) for q in qs]
    c = model.camera(camera).id
    chk.place((*stance_xy_yaw, qs[0]))
    key = hashlib.sha256(json.dumps({"qs": [round(q, 5) for q in qs], "home": np.round(np.concatenate([np.asarray(chk.home[k], float) for k in ("left", "right")]), 5).tolist(), "fov": float(model.cam_fovy[c]),
                                      "res": [int(v) for v in model.cam_resolution[c]], "pos": np.round(model.cam_pos[c], 5).tolist(), "quat": np.round(model.cam_quat[c], 5).tolist(),
                                      "ngeom": int(model.ngeom)}).encode()).hexdigest()[:20]
    path = None if cache_dir is None else Path(cache_dir) / f"silhouette_{key}.npz"
    if path is not None and path.exists():
        try:
            z = np.load(path)
            return np.unpackbits(z["mask"], axis=-1)[..., :int(z["w"])].astype(bool)
        except Exception as e:
            say(f"[bench_stance] silhouette cache unreadable ({e}); rendering again")
    root = model.body("base_link").id

    def under_root(b):
        while b > 0:
            if b == root:
                return True
            b = int(model.body_parentid[b])
        return False

    m2 = copy.copy(model)
    keep = np.array([under_root(int(model.geom_bodyid[g])) for g in range(model.ngeom)])
    m2.geom_rgba = model.geom_rgba.copy()
    m2.geom_rgba[~keep, 3] = 0.0
    W, H = [int(v) for v in model.cam_resolution[c]]
    out = np.zeros((len(qs), H, W), bool)
    for mod in (m2, model):                                  # the robot alone, and the robot in the scene (the finder's own picture): the union, so a pixel either shows counts
        r = mujoco.Renderer(mod, H, W)
        r.enable_segmentation_rendering()
        try:
            for i, q in enumerate(qs):
                chk.place((*stance_xy_yaw, q))
                r.update_scene(chk.d, camera=camera)
                seg = r.render()
                gid = np.where(seg[:, :, 1] == int(mujoco.mjtObj.mjOBJ_GEOM), seg[:, :, 0], -1)
                out[i] |= (gid >= 0) & keep[np.clip(gid, 0, model.ngeom - 1)]
        finally:
            r.close()
    if path is not None:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(".tmp.npz")
        np.savez_compressed(tmp, mask=np.packbits(out, axis=-1), w=W)
        tmp.replace(path)
    return out


def arm_points(model, chk, max_points=500, sample_margin=0.003):
    """Points on the surface of both arms at the zombie pose, in the base frame (base at the origin, yaw 0, pedestal command 0; z the world height with the base resting), thinned to at most max_points
    (the stance finder's HomeClearanceMap takes the same points)."""
    from src.home_clearance_map import _decimate, surface_samples
    chk.place((0.0, 0.0, 0.0, 0.0))
    pts = np.concatenate([surface_samples(model, chk.d, g) for g in chk.arm_geoms])
    cell = 0.01
    P = _decimate(pts, cell)
    while len(P) > max_points:
        cell *= 1.25
        P = _decimate(pts, cell)
    return P


def box_distance(P, c, lo, hi):
    """Distance from points P (M, 3) to the axis-aligned box [c + lo, c + hi] for centres c (..., 3): (..., M)."""
    d = np.maximum(np.maximum(lo - (P - c[..., None, :]), (P - c[..., None, :]) - hi), 0.0)
    return np.sqrt((d ** 2).sum(axis=-1))


def cylinder_distance(P, c, r, z0, z1):
    """Distance from points P (M, 3) to the vertical cylinder of radius r from z0 to z1 whose axis passes through c[..., :2]: (..., M)."""
    dxy = np.hypot(P[:, 0] - c[..., None, 0], P[:, 1] - c[..., None, 1])
    dz = np.maximum(np.maximum(z0 - P[:, 2], P[:, 2] - z1), 0.0)
    return np.hypot(np.maximum(dxy - r, 0.0), dz)


def gripper_view_ok(chk, qs, stance_xy_yaw, margin=STANCE_REQUIREMENTS["view_min_margin"]):
    """Per pedestal command: both grippers (tool point, hand, finger tips) at home are inside the fixed view with the margin (bool (nq,)). They ride with the torso, so the stance does not matter."""
    out = []
    for q in qs:
        mg = chk.view_margin((*stance_xy_yaw, float(q)))["margins"]
        out.append(min(v for k, v in mg.items() if "gripper" in k) >= margin - 1e-9)
    return np.array(out)


def _pixels(cams, qi, P):
    """Image pixel coordinates (x right, y down) and depth of points P (..., 3) in the base frame, for pedestal index qi."""
    th = math.tan(math.radians(cams["fovy"]) / 2)
    W, H = cams["W"], cams["H"]
    pc = (P - cams["pos"][qi]) @ cams["R"][qi]
    depth = -pc[..., 2]
    safe = np.maximum(depth, 1e-6)
    u, v = pc[..., 0] / safe / (th * W / H), pc[..., 1] / safe / th
    return (u + 1) * 0.5 * W, (1 - v) * 0.5 * H, depth


def hidden_fraction(cams, sil, qi, bb, oo, samples):
    """The share of an object's surface sample points that fall on the robot's silhouette, for the object at (b, o) ahead and to the left of the base, for pedestal index qi.

    Args:
        cams (dict): From camera_poses.
        sil (numpy.ndarray): The silhouettes, bool (nq, H, W).
        qi (int): The pedestal index.
        bb, oo (numpy.ndarray): Object positions in the base frame (any shape).
        samples (numpy.ndarray): (K, 3) points on the object's surface: x, y offsets from its centre in the base frame, z the world height minus the base origin's height.

    Returns:
        numpy.ndarray: Shape of bb: the hidden share, 0 to 1 (a point outside the image counts as not hidden: the framing check judges it).
    """
    P = np.stack([bb[..., None] + samples[:, 0], oo[..., None] + samples[:, 1], np.broadcast_to(samples[:, 2], bb.shape + (len(samples),))], axis=-1)
    px, py, depth = _pixels(cams, qi, P)
    H, W = sil.shape[1:]
    ix, iy = np.floor(px).astype(int), np.floor(py).astype(int)
    inside = (ix >= 0) & (ix < W) & (iy >= 0) & (iy < H) & (depth > 0.05)
    hit = np.zeros(P.shape[:-1], bool)
    hit[inside] = sil[qi][iy[inside], ix[inside]]
    return hit.mean(axis=-1)


def count_at(reg, xy_rel, qi, bins=None):
    """The count of a region at one spot: xy_rel = (b, o) of the object in the base frame; qi the pedestal index. 0 outside the region."""
    ib = int(round((xy_rel[0] - reg["b"][0]) / (reg["b"][1] - reg["b"][0])))
    io = int(round((xy_rel[1] - reg["o"][0]) / (reg["o"][1] - reg["o"][0])))
    if not (0 <= ib < len(reg["b"]) and 0 <= io < len(reg["o"])):
        return 0
    return int(counts(reg, bins)[qi, ib, io])


def _place(reg, cnt, X, Y, obj_xy, n, t):
    """The region's counts (nq, ny, nx) on the world grid for an object at obj_xy (bench frame n, t)."""
    d = np.stack([obj_xy[0] - X, obj_xy[1] - Y], axis=-1)           # from the base cell to the object
    bf, of = d @ n, d @ t
    res = reg["b"][1] - reg["b"][0]
    ib = np.rint((bf - reg["b"][0]) / res).astype(int)
    io = np.rint((of - reg["o"][0]) / res).astype(int)
    inb = (ib >= 0) & (ib < len(reg["b"])) & (io >= 0) & (io < len(reg["o"]))
    out = np.zeros((cnt.shape[0],) + X.shape, np.int16)
    out[:, inb] = cnt[:, ib[inb], io[inb]]
    return out


def self_blockers(info, robot, arm, cfg):
    """For the stop message: the obstacles that alone remove every bin of the object's region ("; blocked by [...]"), or ""."""
    reg, zg, others = info
    names = [o["name"] for o in others if not counts(reg, filter_obstacles(reg, robot, arm, zg, [o], cfg)).any()]
    return f"; blocked by {names}" if names else ""


def box_surface_samples(corners, n=7):
    """Points spread over the surface of the axis-aligned box that holds `corners` ((8, 3) world points): n x n on each of the 6 faces."""
    lo, hi = np.min(corners, axis=0), np.max(corners, axis=0)
    g = np.linspace(0.0, 1.0, n)
    A, B = np.meshgrid(g, g)
    A, B = A.ravel(), B.ravel()
    pts = []
    for ax in range(3):
        o1, o2 = [i for i in range(3) if i != ax]
        for side in (lo[ax], hi[ax]):
            P = np.zeros((len(A), 3))
            P[:, ax], P[:, o1], P[:, o2] = side, lo[o1] + A * (hi[o1] - lo[o1]), lo[o2] + B * (hi[o2] - lo[o2])
            pts.append(P)
    return np.concatenate(pts)


def cylinder_surface_samples(xy, radius, z0, z1, n_ang=24, n_z=7):
    """Points over a vertical cylinder's side and its top disc (world), centre xy, from z0 to z1."""
    a = np.linspace(0, 2 * math.pi, n_ang, endpoint=False)
    side = np.array([[xy[0] + radius * math.cos(t), xy[1] + radius * math.sin(t), z] for z in np.linspace(z0, z1, n_z) for t in a])
    top = np.array([[xy[0] + r * math.cos(t), xy[1] + r * math.sin(t), z1] for r in (0.0, 0.5 * radius) for t in a])
    return np.concatenate([side, top])


def widest_run(valid):
    """For each cell of (nq, ny, nx) bool `valid`, the widest run of consecutive True along axis 0 (the first one if several): (width in steps, lowest index, highest index); width 0 where none."""
    run = np.zeros(valid.shape[1:], int)
    best = np.zeros_like(run)
    hi = np.zeros_like(run)
    for i in range(valid.shape[0]):
        run = np.where(valid[i], run + 1, 0)
        upd = run > best
        best = np.where(upd, run, best)
        hi = np.where(upd, i, hi)
    return best, hi - best + 1, hi


def overlay(objects, maps, robot, cams, bench, extra_blocked=None, arm=None, cfg=BENCH_STANCE_CFG, use_cache=True, say=print):
    """Finds the best (x, y, pedestal) for a list of objects (C2d, ranking of F2).

    Args:
        objects (list of dict): Each {"name", "xy" (world), "depth" (from the bench edge), "z_points" (grasp-band heights, world), "surface_z", "corners" ((8, 3) world), "samples" ((K, 3) world),
            "hidden_max", and, as an obstacle for the others, "radius", "z0", "z1"}; optional "supports" (H: the entries under the target, see support_ok) and "extra_obstacles" (cylinders {"name", "xy", "radius",
            "z0", "z1"}: other objects on the table that are not targets of this run).
        maps (dict): {(side, bin): ReachMap}.
        robot (dict): From robot_geometry.
        cams (dict): From camera_poses (with the silhouettes).
        bench (dict): {"yaw": the heading that faces the bench, "open": bench_open}.
        extra_blocked (callable or None): f(X, Y, qs) -> bool (nq, ny, nx), True where the base origin may not be (furniture footprint, zombie clearance); built by the pipeline.
        arm (str or None): Defaults to cfg["arm"].
        cfg (dict): BENCH_STANCE_CFG.
        use_cache (bool): The region cache.
        say (callable): Progress lines.

    Returns:
        dict: "ok", "xy", "q", "qi", "covered", "uncovered", "counts" ({name: count at the best spot}), "ranked" (the best stances in order, at least `nms_distance` apart: dicts with "xy", "q", "qi", "score", "counts"), "score" (objects covered, pedestal run width in m, smallest count, distance to the region's edge in m,
        obstacle clearance in m), "run" ((q_lo, q_hi) of the chosen spot), "grid" (X, Y), "stack" ((nobj, nq, ny, nx) counts), "allowed", "width" ((ny, nx) run width in steps), "qmid" ((ny, nx) index of the chosen
        height per cell), "valid" ((nq, ny, nx): the best number of objects covered), "seconds", "regions".

    Raises:
        BenchStanceError: If no object is covered anywhere (the message names the blockers).
    """
    arm = arm or cfg["arm"]
    n, t = bench_frame(bench["yaw"])
    res = cfg["grid_m"]
    qs = cams["qs"]
    sec = {"region": 0.0, "filter": 0.0, "overlay": 0.0}
    P = np.array([o["xy"] for o in objects], float)
    reach_m = 0.95
    lo, hi = P.min(axis=0) - reach_m, P.max(axis=0) + reach_m
    xs, ys = np.arange(lo[0], hi[0], res) + 0.5 * res, np.arange(lo[1], hi[1], res) + 0.5 * res
    X, Y = np.meshgrid(xs, ys)
    cnts, filt_alone, regs = {}, {}, {}
    t0 = time.time()
    for ob in objects:
        regs[ob["name"]] = get_region(maps, robot, cams, ob["depth"], spec_in_base_frame(ob, bench["yaw"], robot["base_z"]), arm, bench["open"], cfg, use_cache, say)
    sec["region"] = time.time() - t0
    t0 = time.time()
    for ob in objects:
        reg = regs[ob["name"]]
        others = [{"rel": (float((np.asarray(p["xy"]) - np.asarray(ob["xy"])) @ n), float((np.asarray(p["xy"]) - np.asarray(ob["xy"])) @ t)), "radius": p["radius"], "z0": p["z0"], "z1": p["z1"], "name": p["name"]}
                  for p in objects if p is not ob]
        others += [{"rel": (float((np.asarray(p["xy"]) - np.asarray(ob["xy"])) @ n), float((np.asarray(p["xy"]) - np.asarray(ob["xy"])) @ t)), "radius": p["radius"], "z0": p["z0"], "z1": p["z1"], "name": p["name"]}
                   for p in ob.get("extra_obstacles") or []]                              # the other things on the table that are not targets of this run
        zg = 0.5 * (min(ob["z_points"]) + max(ob["z_points"]))
        reach = filter_obstacles(reg, robot, arm, zg, others, cfg)
        sup_ok = support_ok(reg, robot, cams, [{**sp, "target_xy": ob["xy"]} for sp in ob.get("supports") or []], bench["yaw"], cfg)       # H: the supports under the target
        cnts[ob["name"]] = _place(reg, counts(reg, reach, sup_ok), X, Y, ob["xy"], n, t)
        filt_alone[ob["name"]] = (reg, zg, others)
    sec["filter"] = time.time() - t0
    t0 = time.time()
    nq = len(qs)
    allowed = np.ones((nq,) + X.shape, bool) if extra_blocked is None else ~np.asarray(extra_blocked(X, Y, qs), bool)
    names = [o["name"] for o in objects]
    stack = np.stack([cnts[nm] for nm in names]) * allowed[None]                       # (nobj, nq, ny, nx)
    nobj = (stack > 0).sum(axis=0)
    best_n = int(nobj.max())
    if best_n == 0:
        blockers = []
        for ob in objects:
            raw = counts(regs[ob["name"]]).max()
            blockers.append(f"{ob['name']}: best count {int(raw)} without obstacles, 0 with them" + self_blockers(filt_alone[ob["name"]], robot, arm, cfg))
        raise BenchStanceError("no stance covers any of the objects: " + "; ".join(blockers))
    valid = nobj == best_n
    width, q_lo, q_hi = widest_run(valid)                                              # F2: the widest run of consecutive heights per spot, its middle is the spot's height
    qmid = (q_lo + q_hi) // 2
    ys_i, xs_i = np.indices(width.shape)
    minc_all = np.where(stack > 0, stack, 99).min(axis=0)
    minc = np.where(width > 0, minc_all[qmid, ys_i, xs_i], 0)
    edge_q = np.zeros(valid.shape)
    for qi in range(nq):
        if valid[qi].any():
            edge_q[qi] = ndimage.distance_transform_edt(np.pad(valid[qi], 1, constant_values=False))[1:-1, 1:-1] * res
    edge = edge_q[qmid, ys_i, xs_i]
    dist_obs = np.full(width.shape, 9.0)
    for p in objects:
        dist_obs = np.minimum(dist_obs, np.maximum(np.hypot(X - p["xy"][0], Y - p["xy"][1]) - p["radius"], 0.0))
    cand = width > 0
    for key in (width, minc, np.round(edge, 2), np.round(dist_obs, 2) if len(objects) > 1 else None):
        if key is None:
            continue
        cand &= key == key[cand].max()
    iy, ix = [int(v[0]) for v in np.nonzero(cand)]
    qi = int(qmid[iy, ix])
    ranked = []                                                                  # the best stances in order of the ranking, thinned by the finder's distance rule
    cells = np.argwhere(width > 0)
    keys = np.stack([width[cells[:, 0], cells[:, 1]], minc[cells[:, 0], cells[:, 1]], np.round(edge, 2)[cells[:, 0], cells[:, 1]], np.round(dist_obs, 2)[cells[:, 0], cells[:, 1]] if len(objects) > 1 else np.zeros(len(cells))])
    order = np.lexsort(tuple(-keys[i] for i in range(keys.shape[0] - 1, -1, -1)))                  # the first key (the run width) is the most significant
    for ci in order:
        cy, cx = cells[ci]
        if all(math.hypot(X[cy, cx] - r["xy"][0], Y[cy, cx] - r["xy"][1]) >= cfg["rank_min_distance_m"] for r in ranked):
            q_i = int(qmid[cy, cx])
            ranked.append({"xy": (float(X[cy, cx]), float(Y[cy, cx])), "q": float(qs[q_i]), "qi": q_i, "score": (best_n, float(width[cy, cx] * cfg["pedestal_step"]), int(minc[cy, cx]), float(round(edge[cy, cx], 2)), float(dist_obs[cy, cx])),
                           "counts": {nm: int(cnts[nm][q_i, cy, cx]) for nm in names}})
            if len(ranked) >= cfg["rank_keep"]:
                break
    sec["overlay"] = time.time() - t0
    covered = [nm for nm in names if cnts[nm][qi, iy, ix] > 0 and allowed[qi, iy, ix]]
    return {"ok": True, "xy": (float(X[iy, ix]), float(Y[iy, ix])), "q": float(qs[qi]), "qi": qi, "covered": covered, "uncovered": [nm for nm in names if nm not in covered],
            "counts": {nm: int(cnts[nm][qi, iy, ix]) for nm in names}, "ranked": ranked,
            "score": (best_n, float(width[iy, ix] * cfg["pedestal_step"]), int(minc[iy, ix]), float(round(edge[iy, ix], 2)), float(dist_obs[iy, ix])), "run": (float(qs[q_lo[iy, ix]]), float(qs[q_hi[iy, ix]])),
            "grid": (X, Y), "stack": stack, "allowed": allowed, "width": width, "qmid": qmid, "valid": valid, "edge": edge, "minc": minc, "dist_obs": dist_obs, "seconds": sec, "regions": regs}
